    if valid_mse > max(train_mse * 2.8, noise_floor * 2.3, .025):
        return {'label': '出现过拟合信号', 'tone': 'warning', 'description': '训练误差较低，验证误差明显更高。试试降低复杂度、增加样本或加强正则化。'}
    if valid_mse > max(noise_floor * 2.3, .1):
